/// Newton's square root settled to 1e-12, with the steps it took; -1 if it never settles.
/// - a: real[1] (passed a plain number)
/// - cap: int (passed a whole number)
/// - returns r: real[1] (passed a plain number)
/// - returns steps: int (passed a whole number)
/// - returns settled: bool (passed true or false)
#[allow(clippy::too_many_arguments)]
pub fn root(a: f64, cap: i64) -> (f64, i64, bool) {
    let mut r: f64 = 0.0;
    let mut steps: i64 = 0;
    let mut settled: bool = false;
    r = a;
    steps = 0;
    settled = true;
    {
        let __n1: i64 = cap;
        let mut __k0: i64 = 0;
        loop {
            r = (0.5 * (r + (a / r)));
            steps = (steps + 1);
            __k0 += 1;
            if (rt::fabs(((r * r) - a)) < (1.0e-12 * a)) { break; }
            if __k0 >= __n1 {
                settled = false;
                r = ((-(1)) as f64);
                break;
            }
        }
    }
    (r, steps, settled)
}

/// Matrix and vector algebra: M x, M M^T, cross, dot, unit, and element assignment.
/// - x: real[m][3] (passed in m)
/// - y: real[m][3] (passed in m)
/// - rate: real[1/s] (passed in 1/s)
/// - returns mx: real[m/s][3] (passed in m/s)
/// - returns mmt: real[1/s^2][3][3] (passed in 1/s^2)
/// - returns c: real[m^2][3] (passed in m^2)
/// - returns d: real[m^2] (passed in m^2)
