pub fn algebra(x: [f64; 3], y: [f64; 3], rate: f64) -> ([f64; 3], [[f64; 3]; 3], [f64; 3], f64, [f64; 3], [f64; 3]) {
    let mut mx: [f64; 3] = [0.0; 3];
    let mut mmt: [[f64; 3]; 3] = [[0.0; 3]; 3];
    let mut c: [f64; 3] = [0.0; 3];
    let mut d: f64 = 0.0;
    let mut u: [f64; 3] = [0.0; 3];
    let mut s: [f64; 3] = [0.0; 3];
    let mut M: [[f64; 3]; 3] = [[rate, 0.0, 0.0], [0.0, (2.0 * rate), 0.0], [0.0, 0.0, (3.0 * rate)]];
    M[0][1] = (0.5 * rate);
    M[2] = [rate, rate, rate];
    mx = rt::mv(M, x);
    mmt = rt::mm(M, rt::tr(M));
    c = rt::cross(x, y);
    d = rt::dot(x, y);
    u = rt::unit(rt::vsub(x, y));
    s = rt::vadd(rt::vsub(rt::vadd(rt::vneg(x), rt::vscale_l(2.0, y)), crate::selftest::AXES), rt::vdiv(x, 2.0));
    (mx, mmt, c, d, u, s)
}

